// English content for study-plan.html. Reuses R (resources) from study-plan-details.js.
const PLAN_EN={
 phases:{
  0:["Foundation","Repo, vision, AI engineering standards"],
  1:["LLM fundamentals & prompt engineering","Multi-model requirement analyzer"],
  2:["Context engineering & RAG","Project knowledge system"],
  3:["AI Agent engineering","BA, Architect, Developer agents"],
  4:["MCP & tool integration","Agents connected to Jira, Confluence, GitHub"],
  5:["Multi-agent architecture","Four-agent workflow with shared state"],
  6:["Workflow automation","Requirement-to-delivery workflow"],
  7:["Evaluation & observability","Dataset, metrics, traces"],
  8:["Production AI engineering","Secure, observable Docker deployment"],
  9:["Capstone: Autonomous AI Scrum Team","Deliver the Task Management app end-to-end"]
 },
 weeks:{1:"Foundation & environment",2:"Theory + prototype",3:"Multi-provider + comparison",4:"Build the knowledge base",5:"Complete & test retrieval",
  6:"Business Analyst agent",7:"Solution Architect agent",8:"Developer agent",9:"MCP basics",10:"Jira + Confluence",
  11:"Patterns & framework choice",12:"Supervisor + BA → Architect",13:"Developer + QA",14:"Workflow foundations",15:"Requirement → PR",16:"PR → Docs",
  17:"Evaluation dataset",18:"Run evals + tracing",19:"Security & containers",20:"Compose & isolation",21:"CI/CD & operations",
  22:"From request to sprint plan",23:"Implement & review",24:"Deploy & acceptance"}
};

const noteEn=(w,topic)=>({
  title:"Write learning note + commit",
  goal:`Wrap up week ${w}: record what you learned about ${topic} and save it in Git.`,
  time:"45–60 min",
  learn:["A short learning note: Learned · Built · Stuck on · Next week","Conventional Commits (feat:, docs:, test:, chore:)"],
  ai:[["Claude.ai / ChatGPT","Tidy up the note",`Here are my raw notes for week ${w} on ${topic}. Organize them into a learning note with 4 sections: Learned, Built, Still stuck, Next week. Keep my points, don't invent anything:\n\n<paste notes>`]],
  res:[["Conventional Commits","https://www.conventionalcommits.org/"],R.git],
  practice:[`Create docs/learning-notes/week-${String(w).padStart(2,"0")}.md`,"Write the 4 sections, 3–5 bullets each","Commit + push, add the link to the Learning notes log at the bottom of the plan"],
  done:["Note file exists in the repo","At least one honest 'Still stuck' item","Pushed to GitHub","Link added to the log table"]
});

